package in.ac.rtu.medicare.network; import java.io.*; import java.net.*;
public final class NotificationClient { public static String send(String host,int port,String message)throws IOException {try(Socket s=new Socket(host,port);PrintWriter out=new PrintWriter(s.getOutputStream(),true);BufferedReader in=new BufferedReader(new InputStreamReader(s.getInputStream()))){out.println(message.replaceAll("[\\r\\n]"," "));return in.readLine();}} public static void main(String[] a)throws Exception{String host=a.length>0?a[0]:"localhost";int port=a.length>1?Integer.parseInt(a[1]):5050;String message=a.length>2?a[2]:"Appointment reminder";System.out.println(send(host,port,message));} }
